/**
 * The production chat API delivers a FLAT ARRAY of message rows and repeats
 * every conversation-level column on each one:
 *
 *   dealid, crm_entity_id, contact_id, created_at, updated_at, conversation_id
 *
 * Fifty messages therefore carry fifty identical copies of the deal id and the
 * contact id. Grouping them back into one conversation HERE is what makes them
 * one interactions row instead of fifty. The database's unique keys are the
 * second line of defence, not the first: without this node a redelivery would
 * still store correctly, but the execution log would claim work it never did.
 *
 * This node must never throw. The webhook has already answered 200, so an
 * uncaught exception loses the delivery outright with nothing written down.
 * Unusable rows are counted and reported; the whole body is wrapped in a catch.
 */

const SENDER_ROLES = {
  customer: 'customer', client: 'customer', user: 'customer', contact: 'customer',
  agent: 'agent', operator: 'agent', manager: 'agent', employee: 'agent', staff: 'agent',
  bot: 'bot', assistant: 'bot',
  system: 'system',
};

const CONVERSATION_KEYS = ['conversation_id', 'dialog_id', 'chat_id'];
const DEAL_KEYS         = ['dealid', 'deal_id', 'crm_entity_id', 'DealId', 'bitrix_deal_id'];
const CONTACT_KEYS      = ['contact_id', 'contactId', 'CONTACT_ID'];
const TEXT_KEYS         = ['message', 'content', 'text', 'body'];
const SENT_AT_KEYS      = ['timestamp', 'sent_at', 'message_created_at'];
const SENDER_KEYS       = ['sender_role', 'sender', 'role'];
const SENDER_ID_KEYS    = ['sender_id', 'senderId', 'author_id'];
const CONTENT_TYPE_KEYS = ['content_type', 'contentType', 'type'];

function pick(row, keys) {
  for (const k of keys) {
    const v = row[k];
    if (v !== undefined && v !== null && String(v).trim() !== '') return String(v).trim();
  }
  return null;
}

// An ISO string Postgres can cast, or null. NEVER "now": a guessed timestamp
// becomes a response-time metric two steps later and nothing marks it invented.
// The offset is passed through untouched — timestamptz stores the instant, and
// re-rendering it in UTC here would throw away what the source actually said.
function isoOrNull(value) {
  if (value === undefined || value === null) return null;
  const text = String(value).trim().replace(' ', 'T');
  if (!text) return null;
  return Number.isNaN(Date.parse(text)) ? null : text;
}

function msOrNull(value) {
  const text = isoOrNull(value);
  return text === null ? null : Date.parse(text);
}

const stats = {
  rows_in: 0,
  rows_stored: 0,
  conversations: 0,
  rejected_not_an_object: 0,
  rejected_no_key: 0,
  rejected_no_timestamp: 0,
  duplicates_in_batch: 0,
};
let conversations = [];
let crashed = null;

try {
  const incoming = $input.first().json ?? {};
  const body = incoming.body !== undefined ? incoming.body : incoming;

  let rows;
  if (Array.isArray(body))                   rows = body;
  else if (Array.isArray(body?.messages))    rows = body.messages;
  else if (Array.isArray(body?.data))        rows = body.data;
  else if (body && typeof body === 'object') rows = [body];
  else                                       rows = [];
  stats.rows_in = rows.length;

  const byConversation = new Map();

  for (const row of rows) {
    if (!row || typeof row !== 'object' || Array.isArray(row)) {
      stats.rejected_not_an_object++;
      continue;
    }

    // Nothing to file the message under. Storing it against a made-up key would
    // create a thread that no later delivery could ever join.
    const conversationId = pick(row, CONVERSATION_KEYS);
    const dealId = pick(row, DEAL_KEYS);
    const key = conversationId || (dealId ? 'deal-' + dealId : null);
    if (!key) { stats.rejected_no_key++; continue; }

    // chat_messages.sent_at is NOT NULL, and every response-gap metric reads it.
    const sentAt = isoOrNull(pick(row, SENT_AT_KEYS));
    if (!sentAt) { stats.rejected_no_timestamp++; continue; }

    let conv = byConversation.get(key);
    if (!conv) {
      conv = {
        external_id: key,
        external_deal_id: null,
        external_contact_id: null,
        source_created_at: null,
        source_updated_at: null,
        messages: [],
        seen: new Set(),
        watermark: -Infinity,
      };
      byConversation.set(key, conv);
    }

    // Conversation metadata: every row carries a copy and they normally agree.
    // When they disagree the copy from the most recently updated row wins,
    // rather than whichever row happened to be parsed last.
    const mark = msOrNull(row.updated_at) ?? Date.parse(sentAt);
    if (mark >= conv.watermark) {
      conv.watermark = mark;
      conv.external_deal_id    = dealId ?? conv.external_deal_id;
      conv.external_contact_id = pick(row, CONTACT_KEYS) ?? conv.external_contact_id;
      conv.source_updated_at   = isoOrNull(row.updated_at) ?? conv.source_updated_at;
    }
    const created = isoOrNull(row.created_at);
    if (created && (conv.source_created_at === null ||
                    Date.parse(created) < Date.parse(conv.source_created_at))) {
      conv.source_created_at = created;
    }

    const senderRaw = pick(row, SENDER_KEYS);
    const sender = SENDER_ROLES[(senderRaw || '').toLowerCase()] ?? 'unknown';
    const text = pick(row, TEXT_KEYS) ?? '';

    // Same sender, same instant, same words = the same message twice. Nothing
    // in this payload can distinguish a genuine repeat from a redelivery, and
    // the chat_messages unique key collapses it either way — collapsing it here
    // too keeps the count this node reports equal to what the database holds.
    // Compare the parsed instant, not the string: +03:00 and Z can spell one.
    const fingerprint = sender + '\u0000' + Date.parse(sentAt) + '\u0000' + text;
    if (conv.seen.has(fingerprint)) { stats.duplicates_in_batch++; continue; }
    conv.seen.add(fingerprint);

    conv.messages.push({
      sender,
      sender_external_id: pick(row, SENDER_ID_KEYS),
      body: text,
      sent_at: sentAt,
      content_type: pick(row, CONTENT_TYPE_KEYS),
    });
  }

  for (const conv of byConversation.values()) {
    if (conv.messages.length === 0) continue;
    conv.messages.sort((a, b) => Date.parse(a.sent_at) - Date.parse(b.sent_at));
    conversations.push({
      external_id: conv.external_id,
      external_deal_id: conv.external_deal_id,
      external_contact_id: conv.external_contact_id,
      source_created_at: conv.source_created_at,
      source_updated_at: conv.source_updated_at,
      started_at: conv.messages[0].sent_at,
      ended_at: conv.messages[conv.messages.length - 1].sent_at,
      messages: conv.messages,
    });
  }
  conversations.sort((a, b) => a.external_id.localeCompare(b.external_id));
  stats.conversations = conversations.length;
  stats.rows_stored = conversations.reduce((n, c) => n + c.messages.length, 0);
} catch (e) {
  crashed = String((e && e.message) || e);
  conversations = [];
}

// raw_events.external_ref holds a single value, so it is only meaningful when
// the batch speaks about one deal — the normal case. A mixed batch gets null
// rather than a comma-joined string no lookup could ever match.
const dealIds = [...new Set(conversations.map(c => c.external_deal_id).filter(Boolean))];
const externalRef = dealIds.length === 1 ? dealIds[0] : null;

// Written to raw_events.process_error, and NOT cleared by the last node: a row
// with processed_at set and process_error non-null means "stored, minus these".
const rejected = stats.rejected_not_an_object + stats.rejected_no_key + stats.rejected_no_timestamp;
let rejectReason = '';
if (crashed !== null) {
  rejectReason = 'normalizer failed: ' + crashed;
} else if (conversations.length === 0) {
  rejectReason = 'nothing storable: ' + stats.rows_in + ' row(s) in, ' + rejected + ' rejected'
    + ' (' + stats.rejected_not_an_object + ' not objects, '
    + stats.rejected_no_key + ' without conversation_id or dealid, '
    + stats.rejected_no_timestamp + ' without a parseable timestamp)';
} else if (rejected > 0) {
  rejectReason = 'partial: ' + rejected + ' of ' + stats.rows_in + ' row(s) rejected'
    + ' (' + stats.rejected_no_key + ' without a conversation key, '
    + stats.rejected_no_timestamp + ' without a parseable timestamp, '
    + stats.rejected_not_an_object + ' not objects)';
}

return [{ json: {
  conversations,
  external_ids: conversations.map(c => c.external_id),
  external_ref: externalRef,
  reject_reason: rejectReason,
  stats,
} }];
